// VaultServiceServer is the server API for VaultService service.
// All implementations must embed UnimplementedVaultServiceServer
// for forward compatibility.
type VaultServiceServer interface {
	// Client Methods
	SubmitAsset(context.Context, *SubmitAssetRequest) (*SubmitAssetResponse, error)
	GetPortfolio(context.Context, *GetPortfolioRequest) (*GetPortfolioResponse, error)
	// Web3 Methods
	GetWalletChallenge(context.Context, *GetWalletChallengeRequest) (*GetWalletChallengeResponse, error)
	LinkWallet(context.Context, *LinkWalletRequest) (*LinkWalletResponse, error)
	// Plaid Methods
	CreatePlaidLinkToken(context.Context, *CreatePlaidLinkTokenRequest) (*CreatePlaidLinkTokenResponse, error)
	ExchangePlaidPublicToken(context.Context, *ExchangePlaidPublicTokenRequest) (*ExchangePlaidPublicTokenResponse, error)
	// Legacy Methods (Deprecated)
	SyncWealth(context.Context, *SyncWealthRequest) (*SyncWealthResponse, error)
	// Admin Methods (Gated by Admin Middleware)
	AdminVerifyAsset(context.Context, *AdminVerifyAssetRequest) (*AdminVerifyAssetResponse, error)
	// V8.1 — daily net-worth snapshot history.
	ListNetWorthHistory(context.Context, *ListNetWorthHistoryRequest) (*ListNetWorthHistoryResponse, error)
	// V8.2 — Plaid transactions + investment holdings, ingested by
	// backend_go and surfaced for the Flutter dashboard.
	ListPlaidTransactions(context.Context, *ListPlaidTransactionsRequest) (*ListPlaidTransactionsResponse, error)
	ListPlaidHoldings(context.Context, *ListPlaidHoldingsRequest) (*ListPlaidHoldingsResponse, error)
	// V8.3 — allocation donut + stacked-area history.
	GetCurrentAllocation(context.Context, *GetCurrentAllocationRequest) (*GetCurrentAllocationResponse, error)
	ListAllocationHistory(context.Context, *ListAllocationHistoryRequest) (*ListAllocationHistoryResponse, error)
	// V8.5 — real-estate properties + AVM lifecycle.
	ListRealEstateProperties(context.Context, *ListRealEstatePropertiesRequest) (*ListRealEstatePropertiesResponse, error)
	CreateRealEstateProperty(context.Context, *CreateRealEstatePropertyRequest) (*CreateRealEstatePropertyResponse, error)
	RecordManualValuation(context.Context, *RecordManualValuationRequest) (*RecordManualValuationResponse, error)
	RefreshAvmValuation(context.Context, *RefreshAvmValuationRequest) (*RefreshAvmValuationResponse, error)
	DeleteRealEstateProperty(context.Context, *DeleteRealEstatePropertyRequest) (*DeleteRealEstatePropertyResponse, error)
	// V8P2.1 — multi-entity (Personal / LLC / trust / etc.) and
	// per-asset entity assignment.
	ListEntities(context.Context, *ListEntitiesRequest) (*ListEntitiesResponse, error)
	CreateEntity(context.Context, *CreateEntityRequest) (*CreateEntityResponse, error)
	RenameEntity(context.Context, *RenameEntityRequest) (*RenameEntityResponse, error)
	DeleteEntity(context.Context, *DeleteEntityRequest) (*DeleteEntityResponse, error)
	AssignAssetToEntity(context.Context, *AssignAssetToEntityRequest) (*AssignAssetToEntityResponse, error)
	// V8P2.2 — current FX rates for client-side conversion.
	ListLatestFxRates(context.Context, *ListLatestFxRatesRequest) (*ListLatestFxRatesResponse, error)
	// V8P2.5 — cap-table holdings + Carta / Pulley / AngelList
	// connection lifecycle. Cloud pull is honest about being
	// unavailable without API credentials (see OUTSTANDING.md).
	ListCapTableHoldings(context.Context, *ListCapTableHoldingsRequest) (*ListCapTableHoldingsResponse, error)
	CreateCapTableHolding(context.Context, *CreateCapTableHoldingRequest) (*CreateCapTableHoldingResponse, error)
	UpdateCapTableHolding(context.Context, *UpdateCapTableHoldingRequest) (*UpdateCapTableHoldingResponse, error)
	DeleteCapTableHolding(context.Context, *DeleteCapTableHoldingRequest) (*DeleteCapTableHoldingResponse, error)
	ListCapTableConnections(context.Context, *ListCapTableConnectionsRequest) (*ListCapTableConnectionsResponse, error)
	SetCapTableConnectionStatus(context.Context, *SetCapTableConnectionStatusRequest) (*SetCapTableConnectionStatusResponse, error)
	// V8P2.6 — multi-chain wallets. EVM is the only live adapter
	// today; non-EVM chains land in needs_auth until the gateway URLs
	// are configured.
	ListWalletChains(context.Context, *ListWalletChainsRequest) (*ListWalletChainsResponse, error)
	UpsertWalletChain(context.Context, *UpsertWalletChainRequest) (*UpsertWalletChainResponse, error)
	DeleteWalletChain(context.Context, *DeleteWalletChainRequest) (*DeleteWalletChainResponse, error)
	// V8P2.7 — tax surface. v1 ships unrealised gains across Plaid
	// holdings + cap-table line items and a US-CGT (Form 8949) CSV.
	GetTaxSnapshot(context.Context, *GetTaxSnapshotRequest) (*GetTaxSnapshotResponse, error)
	ExportUsCgtCsv(context.Context, *ExportUsCgtCsvRequest) (*ExportUsCgtCsvResponse, error)
	// V8P3.1 — Investment Circles: curated deal-flow gated server-side by the
	// user's cross-pillar Sttattus rank. Locked circles return metadata + the
	// required threshold but withhold the deal room.
	ListInvestmentCircles(context.Context, *ListInvestmentCirclesRequest) (*ListInvestmentCirclesResponse, error)
	GetInvestmentCircle(context.Context, *GetInvestmentCircleRequest) (*GetInvestmentCircleResponse, error)
	ExpressCircleInterest(context.Context, *ExpressCircleInterestRequest) (*ExpressCircleInterestResponse, error)
	// V8P3.2 — concierge advisor desk (Sovereign). Async threads + SLA.
	StartAdvisorThread(context.Context, *StartAdvisorThreadRequest) (*StartAdvisorThreadResponse, error)
	ListAdvisorThreads(context.Context, *ListAdvisorThreadsRequest) (*ListAdvisorThreadsResponse, error)
	GetAdvisorThread(context.Context, *GetAdvisorThreadRequest) (*GetAdvisorThreadResponse, error)
	PostAdvisorMessage(context.Context, *PostAdvisorMessageRequest) (*PostAdvisorMessageResponse, error)
	// V8P3.3 — Wealth Anthology: named-author editorial.
	ListWealthAnthology(context.Context, *ListWealthAnthologyRequest) (*ListWealthAnthologyResponse, error)
	GetWealthArticle(context.Context, *GetWealthArticleRequest) (*GetWealthArticleResponse, error)
	// V8P3.5 — curated private-bank directory (region + tier filter).
	ListPartnerBanks(context.Context, *ListPartnerBanksRequest) (*ListPartnerBanksResponse, error)
	// V8P3.6 — token-based verified-wealth share. Bands only; absolute amounts
	// are never disclosed (discretion-first). Public read at /share/vault/:token.
	CreateVaultShare(context.Context, *CreateVaultShareRequest) (*CreateVaultShareResponse, error)
	ListMyVaultShares(context.Context, *ListMyVaultSharesRequest) (*ListMyVaultSharesResponse, error)
	RevokeVaultShare(context.Context, *RevokeVaultShareRequest) (*RevokeVaultShareResponse, error)
	// V8P4.1 — Annual Wealth Almanac: a gofpdf-rendered PDF of the year's wealth
	// movement, written to R2/S3. Returns the media URL.
	GenerateWealthAlmanac(context.Context, *GenerateWealthAlmanacRequest) (*GenerateWealthAlmanacResponse, error)
	// V8P4.2 — Year-in-Vault recap (pure compute over the user's snapshots).
	GetYearInVault(context.Context, *GetYearInVaultRequest) (*GetYearInVaultResponse, error)
	// V8P4.3 — liquidity stress test: given a cash need, source it across the
	// liquidity ladder (T+0 cash → T+30 marketable → illiquid). Pure compute.
	GetLiquidityStressTest(context.Context, *GetLiquidityStressTestRequest) (*GetLiquidityStressTestResponse, error)
	mustEmbedUnimplementedVaultServiceServer()
}

